import{_ as s,a0 as r,w as l,s as m,ao as p,I as i,x as o,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"使用 Nmon 監控 Linux 的系統性能 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Nmon 監控 Linux 的系統性能 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Nmon 監控 Linux 的系統性能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Nmon 監控 Linux 的系統性能 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151223 Monitor Linux System Performance Using Nmon","title":"使用 Nmon 監控 Linux 的系統性能","tag":"201601","desc":""},"relativePath":"201601/20151223 Monitor Linux System Performance Using Nmon.md","filePath":"[post].md"}'),d={name:"201601/20151223 Monitor Linux System Performance Using Nmon.md"};function u(c,e,h,x,f,w){const n=r("Link");return l(),m("div",null,[e[13]||(e[13]=p(`<h1 id="使用-nmon-監控-linux-的系統性能" tabindex="-1">使用 Nmon 監控 Linux 的系統性能 <a class="header-anchor" href="#使用-nmon-監控-linux-的系統性能" aria-label="Permalink to “使用 Nmon 監控 Linux 的系統性能”">​</a></h1><p>Nmon（得名於 Nigel 的監控器）是IBM的員工 Nigel Griffiths 為 AIX 和 Linux 系統開發的一款計算機性能系統監控工具。Nmon 可以把操作系統的統計數據展示在屏幕上或者存儲到一份數據文件裏，來幫助瞭解計算機資源的使用情況、調整方向和系統瓶頸。這個系統基準測試工具只需要使用一條命令就能得到大量重要的性能數據。使用 Nmon 可以很輕鬆的監控系統的 CPU、內存、網絡、硬盤、文件系統、NFS、高耗進程、資源和 IBM Power 系統的微分區的信息。</p><h3 id="nmon-安裝" tabindex="-1">Nmon 安裝 <a class="header-anchor" href="#nmon-安裝" aria-label="Permalink to “Nmon 安裝”">​</a></h3><p>Nmon 默認是存在於 Ubuntu 的倉庫中的。你可以通過下面的命令安裝 Nmon：</p><pre><code>sudo apt-get install nmon
</code></pre><h3 id="怎麼使用nmon來監控linux的性能" tabindex="-1">怎麼使用Nmon來監控Linux的性能 <a class="header-anchor" href="#怎麼使用nmon來監控linux的性能" aria-label="Permalink to “怎麼使用Nmon來監控Linux的性能”">​</a></h3><p>安裝完成後，通過在終端輸入<code>nmon</code> 命令來啓動 Nmon</p><pre><code>nmon
</code></pre><p>你會看到下面的輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon-output.png" alt="nmon-output"></p><p>從上面的截圖可以看到 nmon 命令列工具完全是交互式運行的，你可以使用快捷鍵來輕鬆查看對應的統計數據。你可以使用下面的 nmon 快捷鍵來顯示不同的系統統計數據：</p><ul><li><code>q</code> : 停止並退出 Nmon</li><li><code>h</code> : 查看幫助</li><li><code>c</code> : 查看 CPU 統計數據</li><li><code>m</code> : 查看內存統計數據</li><li><code>d</code> : 查看硬盤統計數據</li><li><code>k</code> : 查看內核統計數據</li><li><code>n</code> : 查看網絡統計數據</li><li><code>N</code> : 查看 NFS 統計數據</li><li><code>j</code> : 查看文件系統統計數據</li><li><code>t</code> : 查看高耗進程</li><li><code>V</code> : 查看虛擬內存統計數據</li><li><code>v</code> : 詳細模式</li></ul><h3 id="核查-cpu-處理器" tabindex="-1">核查 CPU 處理器 <a class="header-anchor" href="#核查-cpu-處理器" aria-label="Permalink to “核查 CPU 處理器”">​</a></h3><p>如果你想收集關於 CPU 性能相關的統計數據，你應該按下鍵盤上的<code>c</code>鍵，之後你將會看到下面的輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_cpu_output.png" alt="nmon_cpu_output"></p><h3 id="核查高耗進程統計數據" tabindex="-1">核查高耗進程統計數據 <a class="header-anchor" href="#核查高耗進程統計數據" aria-label="Permalink to “核查高耗進程統計數據”">​</a></h3><p>如果想收集系統正在運行的高耗進程的統計數據，按鍵盤上的<code>t</code>鍵，之後你將會看到下面的輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_process_output.jpg" alt="nmon_process_output"></p><h3 id="核查網絡統計數據" tabindex="-1">核查網絡統計數據 <a class="header-anchor" href="#核查網絡統計數據" aria-label="Permalink to “核查網絡統計數據”">​</a></h3><p>如果想收集 Linux 系統的網絡統計數據，按下<code>n</code>鍵，你將會看到下面輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_network_output.png" alt="n_network_output"></p><h3 id="硬盤-i-o-圖表" tabindex="-1">硬盤 I/O 圖表 <a class="header-anchor" href="#硬盤-i-o-圖表" aria-label="Permalink to “硬盤 I/O 圖表”">​</a></h3><p>使用<code>d</code> 鍵獲取硬盤相關的信息，你會看到下面輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_disk_output.png" alt="nmon_disk_output"></p><h3 id="核查內核信息" tabindex="-1">核查內核信息 <a class="header-anchor" href="#核查內核信息" aria-label="Permalink to “核查內核信息”">​</a></h3><p>Nmon 一個非常重要的快捷鍵是<code>k</code>鍵，用來顯示系統內核相關的概要信息。按下<code>k</code>鍵之後，會看到下面輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_kernel_output.png" alt="nmon_kernel_output"></p><h3 id="獲取系統信息" tabindex="-1">獲取系統信息 <a class="header-anchor" href="#獲取系統信息" aria-label="Permalink to “獲取系統信息”">​</a></h3><p>對每個系統管理員來説一個非常有用的快捷鍵是<code>r</code>鍵，可以用來顯示計算機的系統結構、操作系統版本號和 CPU 等不同資源的信息。按下<code>r</code>鍵之後會看到下面輸出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_system_output.png" alt="nmon_system_output"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>還有許多其他的工具做的和 Nmon 同樣的工作，不過 Nmon 對一個 Linux 新手來説還是很友好的。如果你有什麼問題，儘管評論。</p><hr>`,33)),i("p",null,[e[1]||(e[1]=o("via: ",-1)),t(n,{href:"https://www.maketecheasier.com/monitor-linux-system-performance/"},{default:a(()=>[...e[0]||(e[0]=[o("https://www.maketecheasier.com/monitor-linux-system-performance/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=o("作者：",-1)),t(n,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:a(()=>[...e[2]||(e[2]=[o("Hitesh Jethva",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),t(n,{href:"https://github.com/sonofelice"},{default:a(()=>[...e[3]||(e[3]=[o("sonofelice",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}const g=s(d,[["render",u]]);export{k as __pageData,g as default};
